package com.qualitypilot.campaignlab.api;
import com.qualitypilot.campaignlab.execution.*;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;import java.util.List;
@RestController @RequestMapping("/api") public class ExecutionController{private final ExecutionService service;public ExecutionController(ExecutionService s){service=s;}@PostMapping("/marketing-plans/{id}/runs")@ResponseStatus(HttpStatus.CREATED)ExecutionService.RunView start(@RequestHeader(value="X-Role",required=false)String role,@PathVariable String id){return service.start(role,id);}@GetMapping("/runs")List<ExecutionService.RunView> list(){return service.list();}@GetMapping("/runs/{runId}/journeys")List<UserJourney> journeys(@PathVariable String runId){return service.journeys(runId);}@GetMapping("/runs/{runId}/journeys/{userId}/trace")List<NodeExecution> trace(@PathVariable String runId,@PathVariable String userId){return service.trace(runId,userId);}}
